public class Previewer extends AbstractFlashcardViewer {
    private static final String BUNDLE_KEY_INDEX = "index";
    private static final String BUNDLE_KEY_SHOWING_ANSWER = "showingAnswer";

    private long[] mCardList;
    private int mIndex;
    private boolean mShowingAnswer;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        Timber.d("onCreate()");
        super.onCreate(savedInstanceState);

        mCardList = getIntent().getLongArrayExtra("cardList");
        mIndex = getIntent().getIntExtra("index", -1);

        // Restore the state which was saved before the activity was recreated (e.g. on rotation),
        // so that we stay on the card (and side of the card) which was being previewed.
        if (savedInstanceState != null) {
            mIndex = savedInstanceState.getInt(BUNDLE_KEY_INDEX, mIndex);
            mShowingAnswer = savedInstanceState.getBoolean(BUNDLE_KEY_SHOWING_ANSWER, false);
        }

        if (mCardList == null || mCardList.length == 0 || mIndex < 0 || mIndex > mCardList.length - 1) {
            Timber.e("Previewer started with empty card list or invalid index");
            finishWithoutAnimation();
            return;
        }
        showBackIcon();
        // Ensure navigation drawer can't be opened. Various actions in the drawer cause crashes.
        disableDrawerSwipe();
        startLoadingCollection();
    }


    @Override
    public void onSaveInstanceState(Bundle outState) {
        outState.putInt(BUNDLE_KEY_INDEX, mIndex);
        outState.putBoolean(BUNDLE_KEY_SHOWING_ANSWER, mShowingAnswer);
        super.onSaveInstanceState(outState);
    }


    @Override
    protected void onCollectionLoaded(Collection col) {
        super.onCollectionLoaded(col);
        // displayCardQuestion() resets the flag, so remember whether the answer has to be restored
        boolean restoreAnswer = mShowingAnswer;
        mCurrentCard = col.getCard(mCardList[mIndex]);
        displayCardQuestion();
        if (restoreAnswer) {
            displayCardAnswer();
        }
        showBackIcon();
    }

